export default function IndiaMap({ onSelectCategory }) {
  const { t } = useLanguage();
  const [hoveredNode, setHoveredNode] = useState(null);
  const [hoveredState, setHoveredState] = useState(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  // Category Nodes positioned across major regional zones of India
  const categoryNodes = [
    {
      id: "education",
      name: t("mapEducation") || "Education & Scholarships",
      icon: "🎓",
      color: "#8B5CF6", // purple
      bg: "rgba(139, 92, 246, 0.25)",
      border: "#A78BFA",
      x: 275,
      y: 195,
      count: `350+ ${t("mapSchemes") || "Schemes"}`,
    },
    {
      id: "health",
      name: t("mapHealth") || "Health & Ayushman",
      icon: "❤️",
      color: "#EF4444", // red
      bg: "rgba(239, 68, 68, 0.25)",
      border: "#F87171",
      x: 155,
      y: 285,
      count: `180+ ${t("mapSchemes") || "Schemes"}`,
    },
    {
      id: "housing",
      name: t("mapHousing") || "Housing & PM Awas",
      icon: "🏠",
      color: "#10B981", // green
      bg: "rgba(16, 185, 129, 0.25)",
      border: "#34D399",
      x: 430,
      y: 280,
      count: `120+ ${t("mapSchemes") || "Schemes"}`,
    },
    {
      id: "agriculture",
      name: t("mapAgriculture") || "Agriculture & Farmers",
      icon: "🚜",
      color: "#F59E0B", // amber/gold
      bg: "rgba(245, 158, 11, 0.25)",
      border: "#FBBF24",
      x: 290,
      y: 335,
      count: `240+ ${t("mapSchemes") || "Schemes"}`,
    },
    {
      id: "welfare",
      name: t("mapWelfare") || "Social Welfare & Women",
      icon: "👥",
      color: "#6366F1", // indigo
      bg: "rgba(99, 102, 241, 0.25)",
      border: "#818CF8",
      x: 250,
      y: 450,
      count: `310+ ${t("mapSchemes") || "Schemes"}`,
    },
  ];

  const handleMouseMove = (e) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setMousePos({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    });
  };

  return (
    <div
      className="india-map-container"
      aria-label="Interactive India Map of Government Schemes - Survey of India Compliant"
      onMouseMove={handleMouseMove}
    >
      <svg
        viewBox="0 0 640 640"
        className="india-map-svg"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <defs>
          {/* Neon Grid Pattern */}
          <pattern id="grid-pattern" width="24" height="24" patternUnits="userSpaceOnUse">
            <path d="M 24 0 L 0 0 0 24" fill="none" stroke="rgba(56, 189, 248, 0.05)" strokeWidth="0.75" />
          </pattern>

          {/* Glow Filters */}
          <filter id="glow-cyan" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation="5" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          <filter id="glow-monument" x="-30%" y="-30%" width="160%" height="160%">
            <feGaussianBlur stdDeviation="6" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>

          {/* Radial Map Gradients */}
          <radialGradient id="map-bg-radial" cx="50%" cy="48%" r="48%">
            <stop offset="0%" stopColor="rgba(14, 165, 233, 0.16)" />
            <stop offset="60%" stopColor="rgba(14, 165, 233, 0.04)" />
            <stop offset="100%" stopColor="rgba(14, 165, 233, 0)" />
          </radialGradient>

          <linearGradient id="india-border-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="#38BDF8" stopOpacity="0.95" />
            <stop offset="50%" stopColor="#60A5FA" stopOpacity="0.85" />
            <stop offset="100%" stopColor="#818CF8" stopOpacity="0.95" />
          </linearGradient>

          <linearGradient id="state-hover-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
            <stop offset="0%" stopColor="rgba(56, 189, 248, 0.35)" />
            <stop offset="100%" stopColor="rgba(99, 102, 241, 0.25)" />
          </linearGradient>
        </defs>

        {/* Background Radar Grid Circles */}
        <circle cx="320" cy="320" r="290" stroke="rgba(56, 189, 248, 0.04)" strokeWidth="1" strokeDasharray="4 6" />
        <circle cx="320" cy="320" r="220" stroke="rgba(56, 189, 248, 0.06)" strokeWidth="1" strokeDasharray="3 4" />
        <circle cx="320" cy="320" r="150" stroke="rgba(56, 189, 248, 0.08)" strokeWidth="1" />
        <circle cx="320" cy="320" r="75" stroke="rgba(56, 189, 248, 0.1)" strokeWidth="1" />

        {/* Ambient Map Glow */}
        <circle cx="320" cy="320" r="250" fill="url(#map-bg-radial)" />

        {/* State Boundaries Layer (Interactive with Hover) */}
        <g className="india-states-group">
          {INDIA_STATES.map((state, idx) => {
            const isHovered = hoveredState === state.name;
            return (
              <path
                key={`state-${idx}`}
                d={state.d}
                fill={isHovered ? "url(#state-hover-gradient)" : "rgba(14, 165, 233, 0.03)"}
                stroke={isHovered ? "#38BDF8" : "rgba(56, 189, 248, 0.18)"}
                strokeWidth={isHovered ? "1.4" : "0.75"}
                strokeLinejoin="round"
                className="india-state-path"
                onMouseEnter={() => setHoveredState(state.name)}
                onMouseLeave={() => setHoveredState(null)}
              />
            );
          })}
        </g>

        {/* Accurate Survey of India Outer Boundary Path (Bold Cyber Glow Border) */}
        <g className="india-boundary-group" pointerEvents="none">
          <path
            d={OUTER_BOUNDARY_PATH}
            fill="none"
            stroke="url(#india-border-gradient)"
            strokeWidth="1.8"
            strokeLinejoin="round"
            strokeLinecap="round"
            filter="url(#glow-cyan)"
            className="india-main-border"
          />
        </g>

        {/* Constellation Network Connections */}
        <g className="constellation-network" pointerEvents="none">
          {NETWORK_LINES.map(([fromIdx, toIdx], i) => {
            const p1 = CONSTELLATION_POINTS[fromIdx];
            const p2 = CONSTELLATION_POINTS[toIdx];
            if (!p1 || !p2) return null;
            return (
              <line
                key={`line-${i}`}
                x1={p1.x}
                y1={p1.y}
                x2={p2.x}
                y2={p2.y}
                stroke="rgba(56, 189, 248, 0.3)"
                strokeWidth="0.9"
                strokeDasharray="3 3"
                className="constellation-laser-line"
              />
            );
          })}

          {/* Shimmering Node Dots for Major Indian Cities */}
          {CONSTELLATION_POINTS.map((pt, i) => (
            <g key={`pt-${i}`}>
              <circle
                cx={pt.x}
                cy={pt.y}
                r="2.2"
                fill="#38BDF8"
                className="constellation-dot"
              />
              <circle
                cx={pt.x}
                cy={pt.y}
                r="5"
                fill="none"
                stroke="rgba(56, 189, 248, 0.4)"
                strokeWidth="0.7"
                className="constellation-ring"
              />
            </g>
          ))}
        </g>

        {/* Central Monument / Parliament Hub at New Delhi with Indian Flag */}
        <g
          className="central-monument"
          transform="translate(195, 175) scale(0.65)"
          filter="url(#glow-monument)"
          pointerEvents="none"
        >
          {/* Base Platform & Steps */}
          <rect x="0" y="80" width="80" height="6" rx="2" fill="#1E293B" stroke="#38BDF8" strokeWidth="1" />
          <rect x="5" y="75" width="70" height="5" rx="1" fill="#1E293B" stroke="#38BDF8" strokeWidth="0.8" />
          <rect x="10" y="70" width="60" height="5" rx="1" fill="#1E293B" stroke="#38BDF8" strokeWidth="0.8" />

          {/* Main Facade */}
          <rect x="12" y="48" width="56" height="22" rx="2" fill="rgba(15, 23, 42, 0.9)" stroke="#38BDF8" strokeWidth="1" />
          
          {/* Classical Pillars */}
          {[18, 26, 34, 42, 50, 58].map((colX, idx) => (
            <line
              key={`col-${idx}`}
              x1={colX}
              y1="48"
              x2={colX}
              y2="70"
              stroke="#60A5FA"
              strokeWidth="1.2"
              strokeLinecap="round"
            />
          ))}

          {/* Arch Entrance */}
          <path d="M35 70 L35 56 Q40 50 45 56 L45 70 Z" fill="rgba(56, 189, 248, 0.3)" stroke="#38BDF8" strokeWidth="0.75" />

          {/* Dome */}
          <path
            d="M25 48 C25 28, 55 28, 55 48 Z"
            fill="rgba(15, 23, 42, 0.95)"
            stroke="#38BDF8"
            strokeWidth="1.1"
          />
          <path d="M40 28 L40 48" stroke="#38BDF8" strokeWidth="0.75" />

          {/* Flag Mast */}
          <line x1="40" y1="28" x2="40" y2="4" stroke="#E2E8F0" strokeWidth="1.5" />

          {/* Fluttering Indian Tricolor Flag */}
          <g className="indian-flag-flutter" transform="translate(40, 4)">
            {/* Saffron Band */}
            <path d="M0 0 C5 -1, 11 2, 18 0 L18 3 C11 5, 5 2, 0 3 Z" fill="#FF9933" />
            {/* White Band */}
            <path d="M0 3 C5 2, 11 5, 18 3 L18 6 C11 8, 5 5, 0 6 Z" fill="#FFFFFF" />
            {/* Ashoka Chakra */}
            <circle cx="9" cy="4.5" r="1.2" fill="none" stroke="#000088" strokeWidth="0.3" />
            {/* Green Band */}
            <path d="M0 6 C5 5, 11 8, 18 6 L18 9 C11 11, 5 8, 0 9 Z" fill="#138808" />
          </g>
        </g>

        {/* Beams connecting National Hub to Floating Scheme Badges */}
        <g className="monument-beams" pointerEvents="none">
          {categoryNodes.map((node) => (
            <line
              key={`beam-${node.id}`}
              x1="221"
              y1="192"
              x2={node.x}
              y2={node.y}
              stroke={node.color}
              strokeWidth="1"
              strokeOpacity="0.45"
              strokeDasharray="4 4"
              className="radar-beam-pulse"
            />
          ))}
        </g>
      </svg>

      {/* Floating Interactive Scheme Category Badges */}
      <div className="category-pins-layer">
        {categoryNodes.map((node) => {
          const isHovered = hoveredNode === node.id;
          return (
            <div
              key={node.id}
              className={`category-pin-node ${node.id} ${isHovered ? "active" : ""}`}
              style={{
                left: `${(node.x / 640) * 100}%`,
                top: `${(node.y / 640) * 100}%`,
                "--node-color": node.color,
                "--node-bg": node.bg,
                "--node-border": node.border,
              }}
              onMouseEnter={() => setHoveredNode(node.id)}
              onMouseLeave={() => setHoveredNode(null)}
              onClick={() => onSelectCategory && onSelectCategory(node.id)}
              role="button"
              tabIndex={0}
            >
              {/* Radar Wave Rings */}
              <div className="pin-radar-ring ring-1"></div>
              <div className="pin-radar-ring ring-2"></div>

              {/* Main Badge Icon */}
              <div className="pin-icon-bubble">
                <span className="pin-emoji">{node.icon}</span>
              </div>

              {/* Tooltip on Hover */}
              <div className="pin-tooltip">
                <span className="tooltip-title">{node.name}</span>
                <span className="tooltip-count">{node.count}</span>
              </div>
            </div>
          );
        })}
      </div>

      {/* Hover State Badge */}
      {hoveredState && (
        <div
          className="map-state-badge"
          style={{
            left: `${Math.min(Math.max(mousePos.x, 60), 540)}px`,
            top: `${Math.max(mousePos.y - 36, 10)}px`,
          }}
        >
          <span className="state-badge-dot"></span>
          <span className="state-badge-text">{hoveredState}</span>
        </div>
      )}
    </div>
  );
}
